def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Extract one field
        if i == len(line):
            # End of line - add empty field if we just saw a comma, otherwise we're done
            if i > 0 and line[i-1] == ',':
                fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i == len(line):
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid: quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line while in quoted field - unterminated
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field contains a quote - malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                # Skip the comma
                i += 1

    return fields

